'use strict';
/* Maquette uniquement : données en mémoire, résultats et contrôles scénarisés. */
(() => {
 const root=document.querySelector('#workspaces'), dashboard=document.querySelector('.main');
 const items=[['import','Importation'],['quality','Contrôle qualité'],['trajectory','Trajectoires'],['section','Coupes'],['visual','Visualisation']];
 const holes={'DM-001':{depth:100,az:'0°',dip:'−90°',type:'Vertical',survey:'2 stations'},'DM-002':{depth:100,az:'90°',dip:'−45°',type:'Incliné',survey:'2 stations'},'DM-003':{depth:120,az:'0°',dip:'−60°',type:'Incliné',survey:'2 stations'},'DM-004':{depth:80,az:'45°',dip:'−50°',type:'Sans déviation',survey:'Aucune mesure'},'DM-005':{depth:100,az:'180°',dip:'−60°',type:'Profondeur incohérente',survey:'Station à 120 m'},'DM-006':{depth:0,az:'0°',dip:'−90°',type:'Trajectoire invalide',survey:'Profondeur nulle'}};
 const state={space:'import',assistant:true,inspector:true,file:'none',fileType:'Collets',map:{id:'hole_id',x:'collar_x',y:'collar_y',z:'collar_z',depth:'depth'},imported:false,qualityDone:false,corrected:false,preview:false,history:[],qualityFilter:'Toutes',qualitySearch:'',selected:'DM-001',trajectoryStatus:'idle',step:20,sectionName:'Coupe A–A′',azimuth:90,corridor:40,sectionStatus:'idle',holeSelection:['DM-001','DM-002','DM-003'],tracks:{Lithologie:true,Teneurs:true,Altérations:false,Structures:false},view:'Carte',views:{'Carte':{filter:'Tous',collets:true,section:true},'Coupe 2D':{filter:'Tous',collets:true,section:true},'Vue 3D':{filter:'Tous',collets:true,section:true}},simFailure:false};
 let timer=null;
 const labels={import:['01 / PRÉPARER','Importation des données','Associez les champs et examinez vos données avant de confirmer.'],quality:['02 / VÉRIFIER','Contrôle qualité','Comprenez les anomalies et examinez chaque correction avant application.'],trajectory:['03 / CALCULER','Configuration des trajectoires','Vérifiez les données, conventions et hypothèses avant la simulation.'],section:['04 / CONSTRUIRE','Création de coupe','Définissez votre coupe et visualisez son organisation avant génération.'],visual:['05 / EXPLORER','Visualisation 2D & 3D','Explorez les vues et synchronisez uniquement la sélection du forage.']};
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const badge=(text,kind='neutral')=>`<span class="ws-badge ${kind}">${esc(text)}</span>`;
 const btn=(text,action,klass='',disabled=false)=>`<button class="ws-btn ${klass}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;
 const select=(action,value,options,extra='')=>`<select class="ws-select" data-change="${action}" ${extra}>${options.map(o=>{let [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select>`;
 const field=(label,control)=>`<label class="ws-field">${label}${control}</label>`;
 const card=(title,body,right='')=>`<section class="ws-card"><div class="ws-card-head"><h2>${title}</h2>${right}</div><div class="ws-card-body">${body}</div></section>`;
 function side(){return `<aside class="ws-card ws-assistant"><div class="ws-card-head"><div><span class="ws-label">Parcours facultatif</span><h2 style="margin-top:6px">Assistant</h2></div></div><div class="ws-steps">${items.map(([k,n],i)=>`<button class="ws-step ${state.space===k?'active':''}" data-space="${k}"><span class="num">0${i+1}</span><span>${n}</span></button>`).join('')}</div><div class="ws-card-body"><div class="ws-callout info">Vous pouvez accéder à chaque espace directement, dans l’ordre de votre choix.</div></div></aside>`}
 function inspect(){let s=state.space;let rows=s==='import'?[['Famille',state.fileType],['Source',state.file==='none'?'Aucun fichier':state.file==='missing'?'Fichier manquant':'Exemple en mémoire'],['Mapping','Modifiable']]:s==='quality'?[['État',state.qualityDone?'Correction simulée':'À examiner'],['Anomalies',state.qualityDone?'0 dans ce scénario':'1 erreur scénarisée'],['Historique',`${state.history.length} action(s)`]]:s==='trajectory'?[['Forage',state.selected],['Méthode','Angles moyens · V1'],['Résultat',statusName(state.trajectoryStatus)]]:s==='section'?[['Coupe',state.sectionName],['Forages',`${state.holeSelection.length} sélectionné(s)`],['Aperçu',statusName(state.sectionStatus)]]:[['Vue',state.view],['Sélection',state.selected],['Synchronisation','Sélection uniquement']];return `<aside class="ws-card ws-inspector"><div class="ws-card-head"><div><span class="ws-label">Contexte</span><h2 style="margin-top:6px">En un coup d’œil</h2></div></div><div class="ws-card-body"><div class="ws-callout info"><strong>Projet fictif</strong><br>SCR déclaré : EPSG:32629<br>Les illustrations ne sont pas géoréférencées.</div><div class="ws-spacer"></div>${rows.map(([a,b])=>`<div class="ws-inspector-item"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}<div class="ws-spacer"></div><p class="ws-subtle">Les résultats, contrôles et corrections sont scénarisés. Rien n’est écrit dans un projet ou un fichier.</p></div></aside>`}
 function statusName(x){return ({idle:'Non généré',running:'En cours',done:'Terminé · simulé',stale:'Périmé',error:'Échec simulé'})[x]||x}
 const chart=(variant='section')=>variant==='section'?`<svg viewBox="0 0 700 200" preserveAspectRatio="none" role="img" aria-label="Illustration fictive de coupe, non calculée"><rect width="700" height="200" fill="#f5f8f2"/><g stroke="#dce7db" stroke-width="1"><path d="M0 40H700M0 80H700M0 120H700M0 160H700M100 0V200M200 0V200M300 0V200M400 0V200M500 0V200M600 0V200"/></g><path d="M20 61 Q100 40 190 57 T380 52 T680 53" stroke="#779980" stroke-width="2" fill="none"/><path d="M130 53L150 158 M300 55L350 169 M485 55L465 178" stroke="#516e5d" stroke-width="3"/><path class="demo-lithology" d="M128 65L136 98 M136 98L143 128 M143 128L150 158" data-demo-hole="DM-001" stroke="#d5b080" stroke-width="7"/><path class="demo-lithology" d="M297 65L316 106 M316 106L333 140 M333 140L347 167" data-demo-hole="DM-002" stroke="#c99b79" stroke-width="7"/><path class="demo-lithology" d="M484 64L479 111 M479 111L471 148 M471 148L466 176" data-demo-hole="DM-003" stroke="#a9b98e" stroke-width="7"/><g fill="#425d4b" font-family="sans-serif" font-size="11"><text x="104" y="35" data-demo-hole="DM-001">DM-001</text><text x="275" y="35" data-demo-hole="DM-002">DM-002</text><text x="460" y="35" data-demo-hole="DM-003">DM-003</text></g><text x="15" y="190" fill="#6f8272" font-family="sans-serif" font-size="10">SCHÉMA ILLUSTRATIF · SANS ÉCHELLE</text></svg>`:`<svg viewBox="0 0 700 200" preserveAspectRatio="none" role="img" aria-label="Schéma fictif non géoréférencé"><rect width="700" height="200" fill="#ebf1e8"/><g stroke="#d4e3d1" fill="none"><path d="M0 130Q120 20 240 95T480 75T700 40 M0 150Q120 40 240 115T480 95T700 60 M0 170Q120 60 240 135T480 115T700 80"/><path d="M100 0V200M200 0V200M300 0V200M400 0V200M500 0V200M600 0V200M0 50H700M0 100H700M0 150H700"/></g><path class="demo-section-line" d="M90 155L600 65" stroke="#c49269" stroke-dasharray="5 5" stroke-width="2"/><g class="demo-collets" fill="#315c48" stroke="white" stroke-width="3"><circle cx="190" cy="130" data-demo-hole="DM-001" r="7"/><circle cx="345" cy="102" data-demo-hole="DM-002" r="7"/><circle cx="500" cy="75" data-demo-hole="DM-003" r="7"/></g><g fill="#405e4b" font-family="sans-serif" font-size="11"><text x="165" y="115" data-demo-hole="DM-001">DM-001</text><text x="320" y="87" data-demo-hole="DM-002">DM-002</text><text x="475" y="60" data-demo-hole="DM-003">DM-003</text><text x="15" y="187">SCHÉMA ILLUSTRATIF · SANS COORDONNÉES</text></g></svg>`;
 function importPage(){let file=state.file, missing=file==='missing', no=file==='none', bad=file==='issues',unsupported=state.fileType!=='Collets';let rows=no||missing?'':bad?`<tr><td>DM-001</td><td>500000</td><td>800000</td><td>200</td><td>100</td></tr><tr class="${state.corrected?'':'issue'}"><td>${state.corrected?'DM-002':'DM-001'}</td><td>500100</td><td>800000</td><td>210</td><td>100</td></tr>`:`<tr><td>DM-001</td><td>500000</td><td>800000</td><td>200</td><td>100</td></tr><tr><td>DM-002</td><td>500100</td><td>800000</td><td>210</td><td>100</td></tr><tr><td>DM-003</td><td>500200</td><td>800000</td><td>205</td><td>120</td></tr>`;
 let keys=[['id','Identifiant','hole_id'],['x','Est X','collar_x'],['y','Nord Y','collar_y'],['z','Altitude Z','collar_z'],['depth','Profondeur','depth']];let mapping=keys.map(([k,label,src])=>`<tr><td><strong>${label}</strong></td><td>${src}</td><td>${select('map-'+k,state.map[k],[['','— Non associé —'],['hole_id','hole_id'],['collar_x','collar_x'],['collar_y','collar_y'],['collar_z','collar_z'],['depth','depth']])}</td><td>${state.map[k]?badge('Associé','success'):badge('Manquant','error')}</td></tr>`).join('');let unmapped=Object.values(state.map).some(v=>!v),dup=new Set(Object.values(state.map).filter(Boolean)).size!==Object.values(state.map).filter(Boolean).length;
 return card('Source des données',`<div class="ws-fields">${field('Fichier d’exemple (sélection simulée)',select('file',file,[['none','Aucun fichier sélectionné'],['normal','collets.csv — exemple sans anomalie'],['issues','collets_doublon.csv — anomalie'],['missing','fichier_indisponible.csv — manquant']]))}${field('Famille de données',select('fileType',state.fileType,['Collets','Déviations','Lithologie','Teneurs','Altérations','Minéralisations','Structures','Imagerie','RQD','Récupération','Densité']))}</div><p class="ws-subtle">Fichiers prédéfinis en mémoire : aucun fichier local n’est lu. L’aperçu et le mapping ci-dessous sont une démonstration de collets${state.corrected?' avec correction simulée en mémoire':''}.</p>${unsupported?'<div class="ws-callout">Seul le scénario Collets est interactif ici. Les autres familles seront déclinées ultérieurement ; aucun import ne sera simulé pour ce choix.</div>':missing?'<div class="ws-callout error">Fichier fictif indisponible. Sélectionnez un autre exemple pour continuer.</div>':no?'<div class="ws-callout info">Choisissez un exemple pour afficher les correspondances et les premières lignes.</div>':''}`)+`<div class="ws-spacer"></div>`+card('Association des colonnes',no||missing?'<div class="ws-empty"><strong>Aucun mapping à afficher</strong>Sélectionnez d’abord un exemple de fichier.</div>':`<div class="ws-between"><p class="ws-intro">Associez chaque champ au nom de colonne correspondant.</p>${badge(unmapped||dup?'À vérifier':'Mapping illustratif',unmapped||dup?'warning':'success')}</div><div class="ws-spacer"></div><div class="ws-table-wrap"><table class="ws-table"><thead><tr><th>CHAMP DRILLMASTER</th><th>COLONNE SOURCE</th><th>ASSOCIATION</th><th>ÉTAT</th></tr></thead><tbody>${mapping}</tbody></table></div>${unmapped?'<div class="ws-spacer"></div><div class="ws-callout error">Un champ requis n’est pas associé. Sélectionnez une colonne pour continuer.</div>':''}${dup?'<div class="ws-spacer"></div><div class="ws-callout error">Une même colonne est associée à plusieurs champs. Vérifiez les choix.</div>':''}`)+`<div class="ws-spacer"></div>`+card('Aperçu des premières lignes',no||missing?'<div class="ws-empty"><strong>Aucun aperçu</strong>Les données s’afficheront après sélection.</div>':`<div class="ws-table-wrap"><table class="ws-table"><thead><tr><th>hole_id</th><th>collar_x (m)</th><th>collar_y (m)</th><th>collar_z (m)</th><th>depth (m)</th></tr></thead><tbody>${rows}</tbody></table></div><div class="ws-spacer"></div>${bad&&!state.corrected?'<div class="ws-callout error"><strong>1 anomalie scénarisée :</strong> identifiant DM-001 en double. Consultez le contrôle qualité avant de poursuivre.</div>':state.imported?'<div class="ws-callout ok">Importation fictive confirmée. Aucun fichier n’a été modifié.</div>':'<div class="ws-callout info">Aperçu illustratif : aucune détection ni validation réelle n’est effectuée.</div>'}`)+`<div class="ws-spacer"></div><div class="ws-row">${btn('Confirmer l’import simulé','confirm-import','primary',no||missing||unmapped||dup||unsupported)}${btn('Annuler','cancel-import')}${btn('Voir le contrôle qualité →','go-quality')}</div>`}
 function qualityPage(){let no=state.file==='none'||state.file==='missing'||!state.imported, fixed=state.qualityDone||state.corrected;let found=state.qualitySearch.trim()===''||'dm-001 identifiant doublon collets'.includes(state.qualitySearch.toLowerCase());let filtered=state.qualityFilter==='Toutes'||state.qualityFilter==='Erreurs';return card('Synthèse du contrôle',`<div class="ws-fields three"><div class="ws-callout ${!no&&!fixed?'error':'ok'}"><strong>${!no&&!fixed?'01':'00'} erreur</strong><br>Scénario d’identifiant</div><div class="ws-callout"><strong>00 avertissement</strong><br>Exemple prédéfini</div><div class="ws-callout info"><strong>${fixed?'Terminée':'À examiner'}</strong><br>Validation simulée</div></div><p class="ws-subtle">Ces chiffres sont scénarisés et ne constituent pas un contrôle des données. L’exemple d’erreur représente un identifiant de collet en double.</p>`)+`<div class="ws-spacer"></div>`+card('Anomalies',`<div class="ws-fields">${field('Gravité',select('qualityFilter',state.qualityFilter,['Toutes','Erreurs','Avertissements','Informations']))}${field('Rechercher',`<input class="ws-input" data-change="qualitySearch" placeholder="Forage, famille, problème…" value="${esc(state.qualitySearch)}">`)}</div><div class="ws-spacer"></div>${no?'<div class="ws-empty"><strong>Aucune donnée sélectionnée</strong>Revenez à l’importation pour choisir et confirmer un exemple.</div>':fixed?'<div class="ws-callout ok">Aucune anomalie restante dans ce scénario. Aucune validation réelle n’a été effectuée.</div>':found&&filtered?`<div class="ws-table-wrap"><table class="ws-table"><thead><tr><th>GRAVITÉ</th><th>FAMILLE</th><th>ENREGISTREMENT</th><th>PROBLÈME</th><th>ACTION</th></tr></thead><tbody><tr class="issue"><td>${badge('Erreur','error')}</td><td>Collets</td><td>DM-001 · ligne 3</td><td>Identifiant en double</td><td><button data-action="locate-issue">Examiner</button></td></tr></tbody></table></div><div class="ws-spacer"></div><div class="ws-callout error"><strong>Pourquoi ?</strong> Deux collets utilisent le même identifiant. Une association fiable aux autres tables nécessite un identifiant unique.</div><div class="ws-spacer"></div><p class="ws-subtle">Proposition fictive : corriger le second identifiant en DM-002. Vérifiez cette correspondance dans les sources avant toute correction réelle.</p>${state.preview?`<div class="ws-callout"><strong>Aperçu avant confirmation</strong><br>Ligne 3 · hole_id : <s>DM-001</s> → <strong>DM-002</strong><br>Action en mémoire uniquement ; aucun fichier modifié.</div><div class="ws-spacer"></div><div class="ws-row">${btn('Appliquer la correction simulée','apply-fix','primary')}${btn('Annuler l’aperçu','cancel-fix')}</div>`:`${btn('Voir l’aperçu de correction','preview-fix','primary')}`}`:'<div class="ws-empty"><strong>Aucun résultat pour ce filtre</strong>Essayez une autre recherche ou gravité.</div>'}`)+`<div class="ws-spacer"></div>`+card('Historique des corrections',state.history.length?state.history.map(x=>`<div class="ws-log"><strong>Correction simulée</strong><br>${esc(x)}</div>`).join(''):'<p class="ws-subtle">Aucune correction dans cette session fictive. L’historique n’est pas enregistré.</p>')+`<div class="ws-spacer"></div><div class="ws-row">${btn('← Retour à l’import','go-import')}${btn('Configurer les trajectoires →','go-trajectory','primary')}</div>`}
 function trajectoryPage(){let h=holes[state.selected],bad=h.depth<=0||state.selected==='DM-005',missing=state.selected==='DM-004';let status=state.trajectoryStatus;
 return card('Forage et données d’entrée',`<div class="ws-fields">${field('Identifiant du forage',select('hole',state.selected,Object.keys(holes).map(k=>[k,`${k} · ${holes[k].type}`])))}${field('Méthode de calcul',select('method','Angles moyens · méthode V1',['Angles moyens · méthode V1']))}</div><div class="ws-spacer"></div><div class="ws-fields three"><div class="ws-inspector-item"><span>Collet</span><strong>${state.selected==='DM-001'?'500000 E · 800000 N':'Données fictives'}</strong></div><div class="ws-inspector-item"><span>Azimut / dip</span><strong>${h.az} / ${h.dip}</strong></div><div class="ws-inspector-item"><span>Profondeur</span><strong>${h.depth} m</strong></div></div><p class="ws-subtle">Déviations : ${h.survey}. Dip signé : négatif vers le bas, positif vers le haut ; convention V1.</p>${bad?`<div class="ws-callout error"><strong>Données incohérentes :</strong> ${state.selected==='DM-005'?'une station est au-delà de la profondeur déclarée.':'profondeur nulle, trajectoire inexploitable.'} Corrigez les données avant de poursuivre.</div>`:missing?'<div class="ws-callout"><strong>Déviation absente.</strong> Scénario : direction du collet utilisée pour une trajectoire rectiligne ; hypothèse à confirmer. Aucun calcul réel.</div>':'<div class="ws-callout ok">Scénario prêt à être simulé. La validité scientifique n’est pas évaluée par la maquette.</div>'}`)+`<div class="ws-spacer"></div>`+card('Paramètres et résultat',`${field('Pas d’échantillonnage (m)',`<input class="ws-input" type="number" min="1" max="100" data-change="sampling" value="${state.step}">`)}<p class="ws-subtle">Modifier un paramètre après la simulation marque le résultat comme périmé. La méthode proposée est celle de la V1 ; aucune autre méthode n’est inventée.</p><div class="ws-row">${btn('Simuler le calcul','simulate-trajectory','primary',bad||status==='running')}${btn('Annuler','cancel-trajectory','',status!=='running')}${btn('Simuler un échec','trajectory-failure','danger',status==='running')}</div><div class="ws-spacer"></div>${status==='running'?'<div class="ws-progress"><span></span></div><p class="ws-subtle">Simulation en cours…</p>':status==='done'?'<div class="ws-callout ok">Simulation terminée. Le schéma ci-dessous n’est pas une trajectoire calculée.</div>':status==='stale'?'<div class="ws-callout">Paramètre modifié : résultat précédent périmé. Relancez la simulation.</div>':status==='error'?'<div class="ws-callout error">Échec simulé : aucune sortie n’a été créée. Vérifiez les données et réessayez.</div>':'<div class="ws-callout info">Aucun résultat. Configurez puis lancez une simulation.</div>'}<div class="ws-spacer"></div><div class="ws-chart">${chart('section')}</div><p class="ws-subtle">Illustration non calculée, sans échelle ; non liée au forage sélectionné.</p>`)+`<div class="ws-spacer"></div><div class="ws-row">${btn('← Contrôle qualité','go-quality')}${btn('Créer une coupe →','go-section','primary')}</div>`}
 function sectionPage(){let checks=Object.keys(state.tracks).map(k=>`<label class="ws-check"><input type="checkbox" data-change="track-${k}" ${state.tracks[k]?'checked':''}> ${k}</label>`).join('');let holeChecks=['DM-001','DM-002','DM-003'].map(k=>`<label class="ws-check"><input type="checkbox" data-change="selecthole-${k}" ${state.holeSelection.includes(k)?'checked':''}> ${k} · ${holes[k].depth} m</label>`).join('');return card('Définition de la coupe',`<div class="ws-fields three">${field('Nom de la coupe',`<input class="ws-input" data-change="sectionName" value="${esc(state.sectionName)}">`)}${field('Orientation proposée (°)',`<input class="ws-input" type="number" min="0" max="360" data-change="azimuth" value="${state.azimuth}">`)}${field('Corridor (m)',`<input class="ws-input" type="number" min="1" max="500" data-change="corridor" value="${state.corridor}">`)}</div><p class="ws-subtle">Positionnement illustratif A–A′ : la carte ci-dessous ne représente pas une ligne géoréférencée.</p><div class="ws-chart">${chart('map')}</div>`)+`<div class="ws-spacer"></div>`+card('Forages et contenu géologique',`<div class="ws-fields"><div><h3 class="ws-mini-heading">Forages inclus</h3>${holeChecks}</div><div><h3 class="ws-mini-heading">Pistes à afficher</h3>${checks}</div></div><p class="ws-subtle">Couleurs : référentiel fictif, à configurer ultérieurement. Les pistes cochées sont des options d’aperçu, pas des données générées. Seule la piste lithologie modifie le schéma de cette version.</p>`)+`<div class="ws-spacer"></div>`+card('Aperçu de coupe',`<div class="ws-between"><p class="ws-intro">Vue d’organisation, non calculée et sans échelle.</p>${badge(statusName(state.sectionStatus),state.sectionStatus==='stale'?'warning':'neutral')}</div><div class="ws-spacer"></div><div class="ws-chart">${chart('section')}</div><div class="ws-map-legend"><span><i style="background:#d5b080"></i>Lithologie illustrative</span><span><i style="background:#c99b79"></i>Intervalles illustratifs</span></div>${state.holeSelection.length===0?'<div class="ws-callout error">Sélectionnez au moins un forage pour simuler la génération.</div>':''}<div class="ws-spacer"></div><div class="ws-row">${btn('Simuler la génération','generate-section','primary',state.holeSelection.length===0)}${btn('Simuler un export','export-section')}${btn('Annuler les réglages','reset-section')}</div><p class="ws-subtle">L’export est une démonstration : aucun fichier n’est créé. La sélection des forages et la piste lithologie masquent les éléments correspondants ; orientation et autres pistes ne transforment pas le schéma.</p>`)+`<div class="ws-spacer"></div><div class="ws-row">${btn('← Trajectoires','go-trajectory')}${btn('Explorer les vues →','go-visual','primary')}</div>`}
 function visualPage(){return card('Espace de visualisation',`<div class="ws-between"><div class="ws-toolbar">${['Carte','Coupe 2D','Vue 3D'].map(v=>`<button class="ws-toggle ${state.view===v?'active':''}" data-viewspace="${v}" aria-pressed="${state.view===v}">${v}</button>`).join('')}</div>${badge('Illustration fictive','neutral')}</div><div class="ws-spacer"></div><div class="ws-chart" style="height:290px">${state.view==='Carte'?chart('map'):state.view==='Coupe 2D'?chart('section'):`<svg viewBox="0 0 700 200" preserveAspectRatio="none" role="img" aria-label="Schéma 3D fictif non calculé"><rect width="700" height="200" fill="#edf3ec"/><path d="M140 115 L375 155 L585 102 L354 66 Z" stroke="#b3cbb2" fill="#e5eee2"/><g stroke="#d1e2cd"><path d="M200 125L410 70M270 138L480 80M340 148L550 90M196 101L430 142M260 85L490 127"/></g><g stroke="#789b7e" stroke-width="3"><path d="M245 100l15 65M340 118l27 58M455 101l-5 60"/></g><g class="demo-collets" fill="#315c48"><circle cx="245" cy="100" data-demo-hole="DM-001" r="5"/><circle cx="340" cy="118" data-demo-hole="DM-002" r="5"/><circle cx="455" cy="101" data-demo-hole="DM-003" r="5"/></g><text x="20" y="188" fill="#607768" font-family="sans-serif" font-size="10">ILLUSTRATION 3D · AUCUNE GÉOMÉTRIE CALCULÉE</text></svg>`}</div>${state.views[state.view].filter==='Sélection uniquement'&&!['DM-001','DM-002','DM-003'].includes(state.selected)?'<div class="ws-callout">Aucun symbole disponible pour ce forage dans ce schéma simplifié.</div>':''}<div class="ws-map-legend"><span><i style="background:#315c48"></i>Forages fictifs</span><span><i style="background:#c49269"></i>Coupe illustrative</span></div><div class="ws-callout info">La sélection du forage est partagée entre les vues. La caméra, les filtres et les couches restent propres à la vue ; ces changements sont purement visuels.</div><div class="ws-spacer"></div><div class="ws-fields">${field('Forage sélectionné',select('hole',state.selected,Object.keys(holes).map(k=>[k,`${k} · ${holes[k].type}`])))}${field('Filtre de vue (local)',select('viewFilter',state.views[state.view].filter,['Tous','Sélection uniquement']))}</div><div class="ws-spacer"></div><h3 class="ws-mini-heading">Couches visibles · état local simulé</h3><div class="ws-row"><label class="ws-check"><input type="checkbox" data-change="layer-collets" ${state.views[state.view].collets?'checked':''}> Collets</label><label class="ws-check"><input type="checkbox" data-change="layer-section" ${state.views[state.view].section?'checked':''}> Tracé de coupe</label></div><p class="ws-subtle">Les réglages sont mémorisés séparément pour chaque vue. Le filtre et les couches agissent sur les symboles du schéma lorsque disponibles ; ce ne sont pas des couches QGIS.</p>`)+`<div class="ws-spacer"></div><div class="ws-row">${btn('← Modifier la coupe','go-section')}${btn('Réinitialiser les options de vue','reset-view')}</div>`}
 const pageFns={import:importPage,quality:qualityPage,trajectory:trajectoryPage,section:sectionPage,visual:visualPage};
 function render(){const [ey,title,subtitle]=labels[state.space];root.innerHTML=`<div class="ws-top"><div><div class="ws-crumb">DRILLMASTER / ESPACES DE TRAVAIL / ${ey}</div><h1>${title}</h1><p>${subtitle}</p></div><button class="ws-back" data-action="home">← Vue d’ensemble</button></div><nav class="ws-nav" aria-label="Accès directs aux cinq espaces">${items.map(([k,n])=>`<button data-space="${k}" class="${state.space===k?'active':''}" ${state.space===k?'aria-current="page"':''}>${n}</button>`).join('')}</nav><div class="ws-info"><span><b>Prototype interactif · données fictives.</b> Aucun fichier, calcul, contrôle scientifique ou export réel.</span><span>Projet fictif : EPSG:32629 · illustrations non géoréférencées</span></div><div class="ws-screen-info"><span>Assistant facultatif · sélection et contexte en mémoire uniquement</span><div class="ws-controls"><button data-action="toggle-assistant">${state.assistant?'Masquer':'Afficher'} l’assistant</button><button data-action="toggle-inspector">${state.inspector?'Masquer':'Afficher'} le contexte</button></div></div><div class="ws-grid ${state.assistant?'':'no-assistant'} ${state.inspector?'':'no-inspector'}" style="margin-top:14px">${state.assistant?side():''}<div class="ws-center">${pageFns[state.space]()}</div>${state.inspector?inspect():''}</div><div class="ws-footer"><span>MAQUETTE · les résultats sont scénarisés, non exploitables scientifiquement.</span><span>ÉTAPE DE CONCEPTION / V02</span></div>`;if(state.space==='visual'){const chart=root.querySelector('.ws-chart');const cfg=state.views[state.view];chart.querySelectorAll('.demo-collets').forEach(x=>x.style.display=cfg.collets?'':'none');chart.querySelectorAll('.demo-section-line').forEach(x=>x.style.display=cfg.section?'':'none');chart.querySelectorAll('[data-demo-hole]').forEach(x=>{if(cfg.filter==='Sélection uniquement' && x.dataset.demoHole!==state.selected)x.style.display='none'; if(x.dataset.demoHole===state.selected && x.tagName.toLowerCase()==='circle')x.setAttribute('stroke','#c48d5c')})}if(state.space==='section'){const charts=root.querySelectorAll('.ws-chart');const preview=charts[charts.length-1];preview.querySelectorAll('[data-demo-hole]').forEach(x=>{if(!state.holeSelection.includes(x.dataset.demoHole))x.style.display='none'});if(!state.tracks.Lithologie)preview.querySelectorAll('.demo-lithology').forEach(x=>x.style.display='none')}}
 function go(k){if(timer){clearTimeout(timer);timer=null;if(state.trajectoryStatus==='running')state.trajectoryStatus='idle'}state.space=k;dashboard.hidden=true;root.hidden=false;render();window.scrollTo(0,0)}
 function home(){root.hidden=true;dashboard.hidden=false;window.scrollTo(0,0)}
 window.openPrototypeWorkspace=go;
 document.querySelectorAll('[data-open-space]').forEach(b=>b.onclick=()=>go(b.dataset.openSpace));
 // Relier les entrées existantes sans déclencher les dialogues de la première version.
 document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',e=>{e.stopImmediatePropagation();let k=b.dataset.nav;if(k==='workspace')home();else go(({data:'import',quality:'quality',visual:'visual'})[k]);},true));
 document.querySelectorAll('.step').forEach(b=>b.addEventListener('dblclick',()=>go(({data:'import',geometry:'trajectory',section:'section'})[b.dataset.step]||'import')));
 root.addEventListener('click',e=>{let target=e.target.closest('[data-space],[data-action],[data-viewspace]');if(!target)return;if(target.dataset.space){go(target.dataset.space);return}if(target.dataset.viewspace){state.view=target.dataset.viewspace;render();return}let a=target.dataset.action;if(a==='home'){home();return}if(a.startsWith('go-')){go(({ 'go-import':'import','go-quality':'quality','go-trajectory':'trajectory','go-section':'section','go-visual':'visual'})[a]);return}
 switch(a){case'toggle-assistant':state.assistant=!state.assistant;break;case'toggle-inspector':state.inspector=!state.inspector;break;case'confirm-import':state.imported=true;state.qualityDone=state.file==='normal';state.corrected=false;state.preview=false;break;case'cancel-import':state.file='none';state.imported=false;state.qualityDone=false;state.corrected=false;state.preview=false;break;case'locate-issue':state.preview=true;break;case'preview-fix':state.preview=true;break;case'cancel-fix':state.preview=false;break;case'apply-fix':state.preview=false;state.corrected=true;state.qualityDone=true;state.history.push('Collets · ligne 3 · DM-001 → DM-002 ; aucune écriture.');break;case'simulate-trajectory':state.trajectoryStatus='running';render();timer=setTimeout(()=>{state.trajectoryStatus='done';timer=null;render()},1100);return;case'cancel-trajectory':clearTimeout(timer);timer=null;state.trajectoryStatus='idle';break;case'trajectory-failure':state.trajectoryStatus='error';break;case'generate-section':state.sectionStatus='done';break;case'export-section':toast('Export simulé : aucun fichier n’a été créé.');return;case'reset-section':state.sectionName='Coupe A–A′';state.azimuth=90;state.corridor=40;state.holeSelection=['DM-001','DM-002','DM-003'];state.tracks={Lithologie:true,Teneurs:true,Altérations:false,Structures:false};state.sectionStatus='idle';break;case'reset-view':state.views[state.view]={filter:'Tous',collets:true,section:true};break}render()});
 root.addEventListener('change',e=>{let el=e.target,k=el.dataset.change;if(!k)return;let value=el.value;
 if(k==='file'){state.file=value;state.imported=false;state.qualityDone=false;state.corrected=false;state.preview=false}
 else if(k==='fileType')state.fileType=value;else if(k.startsWith('map-'))state.map[k.slice(4)]=value;else if(k==='qualityFilter')state.qualityFilter=value;else if(k==='qualitySearch')state.qualitySearch=value;else if(k==='hole'){state.selected=value;if(state.trajectoryStatus==='done')state.trajectoryStatus='stale'}else if(k==='sampling'){let n=Number(value);if(!Number.isFinite(n)||n<1||n>100){toast('Le pas doit être compris entre 1 et 100 m dans ce scénario.');render();return}state.step=n;if(state.trajectoryStatus==='done')state.trajectoryStatus='stale'}else if(k==='sectionName'){state.sectionName=value.trim()||'Coupe A–A′';if(state.sectionStatus==='done')state.sectionStatus='stale'}else if(k==='azimuth'||k==='corridor'){let n=Number(value),valid=Number.isFinite(n)&&(k==='azimuth'?n>=0&&n<=360:n>=1&&n<=500);if(!valid){toast('Valeur hors limites pour ce scénario.');render();return}state[k]=n;if(state.sectionStatus==='done')state.sectionStatus='stale'}else if(k.startsWith('track-')){state.tracks[k.slice(6)]=el.checked;if(state.sectionStatus==='done')state.sectionStatus='stale'}else if(k.startsWith('selecthole-')){let id=k.slice(11);state.holeSelection=el.checked?[...new Set([...state.holeSelection,id])]:state.holeSelection.filter(x=>x!==id);if(state.sectionStatus==='done')state.sectionStatus='stale'}else if(k==='viewFilter')state.views[state.view].filter=value;else if(k.startsWith('layer-'))state.views[state.view][k.slice(6)]=el.checked;render()});
})();
